#include <cstdint>
#include <optional>
#include <utility>

enum class Side : std::uint8_t {
    Buy = 1,
    Sell = 2
};

std::uint8_t to_wire(Side side) {
    return std::to_underlying(side);
}

std::optional<Side> from_wire(std::uint8_t value) {
    switch (value) {
        case 1: return Side::Buy;
        case 2: return Side::Sell;
        default: return std::nullopt;
    }
}

#include <iostream>
#include <iterator>
#include <vector>

void print_reverse(const std::vector<int>& values) {
    // Signed index: std::ssize gives -1 for an empty vector, so the loop
    // simply never runs.
    for (auto i = std::ssize(values) - 1; i >= 0; --i) {
        std::cout << values[static_cast<std::size_t>(i)] << '\n';
    }

    // Unsigned, post-decrement: tests the old value, then uses the new one.
    for (auto i = values.size(); i-- > 0;) {
        std::cout << values[i] << '\n';
    }
}

#include <algorithm>
#include <cmath>

bool almost_equal(double lhs, double rhs,
                  double relative_tolerance,
                  double absolute_tolerance) {
    double difference = std::abs(lhs - rhs);
    double scale = std::max(std::abs(lhs), std::abs(rhs));
    return difference <=
           std::max(absolute_tolerance, relative_tolerance * scale);
}

#include <cmath>

bool accept_price(double price, double maximum) {
    // Every ordered comparison with NaN is false, so `price > maximum`
    // is false for a NaN price and an inverted check would accept it.
    if (!std::isfinite(price)) {
        return false;
    }
    return price <= maximum;
}

#include <cstddef>
#include <vector>

long sum(const std::vector<int>& values) {
    long total = 0;
    for (int v : values) {
        total += v;
    }
    return total;
}

// A parameter written `int values[10]` is adjusted to `int*`: the bound is
// documentation the compiler discards, so the length has to be passed.
long sum(const int* values, std::size_t count) {
    long total = 0;
    for (std::size_t i = 0; i < count; ++i) {
        total += values[i];
    }
    return total;
}

#include <cmath>
#include <cstdint>
#include <limits>
#include <optional>

std::optional<std::int64_t> price_to_ticks(double price, double tick_size) {
    if (!std::isfinite(price) || !std::isfinite(tick_size) || tick_size <= 0.0) {
        return std::nullopt;
    }

    double ticks = std::round(price / tick_size);

    // static_cast documents intent but adds no range check: converting an
    // out-of-range double to an integer type is undefined behaviour.
    constexpr double limit = static_cast<double>(std::numeric_limits<std::int64_t>::max());
    if (ticks < -limit || ticks > limit) {
        return std::nullopt;
    }

    return static_cast<std::int64_t>(ticks);
}

#include <string>

void deduction_forms(const std::string& view) {
    auto value = view;         // std::string — copies
    auto& alias = view;        // const std::string& — aliases, read-only
    const auto& ref = view;    // const std::string& — aliases, read-only
    auto&& fwd = view;         // const std::string& — binds to this lvalue
    auto* ptr = &view;         // const std::string* — needs a pointer initialiser

    (void)value; (void)alias; (void)ref; (void)fwd; (void)ptr;
}
